pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        // Restrict inputs: the reference (transfer) works for any receiver and positive amount
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);
        // The reference version: when sendTo succeeds, the contract's balance remains 0 (no ether sent to contract)
        // The buggy version with call may revert if the receiver is a contract without a payable fallback
        // We'll call using a prank as the owner (vm.addr(1))
        address owner = vm.addr(1);
        // Fund the owner with enough ether
        vm.deal(owner, amount);
        vm.prank(owner);
        // Attempt the call; the reference should always succeed for any valid receiver and amount
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.sendTo.selector, receiver, amount));
        // The general rule: the call should succeed (i.e., not revert) for any valid input
        assertTrue(ok);
    }
}

