pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint amount) public {
        vm.assume(amount > 0);
        vm.assume(caller != address(0));

        address owner = address(this);  // owner is the deployer
        uint256 initialOwnerBalance = owner.balance;
        uint256 initialContractBalance = address(c).balance;
        uint256 initialSum = initialOwnerBalance + initialContractBalance;

        vm.deal(address(c), initialContractBalance);

        uint256 amountToSend = bound(amount, 1, address(c).balance);

        vm.startPrank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", address(0xdead), amountToSend));
        vm.stopPrank();

        uint256 finalOwnerBalance = owner.balance;
        uint256 finalContractBalance = address(c).balance;
        uint256 finalSum = finalOwnerBalance + finalContractBalance;

        assertTrue(initialSum - finalSum == amountToSend || (!success && finalSum == initialSum));
    }
}

